import{_ as i,o as e,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2016-JUN-21 -- Ceph Tech Talks: Bluestore","description":"","frontmatter":{"title":"2016-JUN-21 -- Ceph Tech Talks: Bluestore","date":"2016-06-23T00:00:00.000Z","updated":"2016-06-23T00:00:00.000Z","tags":["Ceph","Bluestore","分布式存储","性能优化","存储后端"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-JUN-21_--_Ceph_Tech_Talks_-_Bluestore.md","filePath":"posts/2016/2016-JUN-21_--_Ceph_Tech_Talks_-_Bluestore.md","lastUpdated":1780459816000}'),s={name:"posts/2016/2016-JUN-21_--_Ceph_Tech_Talks_-_Bluestore.md"};function r(n,l,a,p,u,c){return e(),o("div",null,[...l[0]||(l[0]=[t('<p>subtitle: 2016-JUN-21_--<em>Ceph_Tech_Talks</em>-_Bluestore</p><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2016年6月21日</p><p><strong>会议主题</strong>： Ceph Tech Talks - Bluestore 后端存储介绍</p><p><strong>参会人员</strong>： Sage (主讲人) 及其他 Ceph 团队成员</p><p><strong>会议内容</strong>：</p><p><strong>一、会议背景</strong></p><ul><li>Ceph 是一个可扩展、高性能的分布式存储系统，提供对象、块和文件存储接口。</li><li>Ceph 的存储后端是 Rados，它使用文件系统来存储数据。</li><li>传统的文件存储方式存在性能瓶颈和复杂性，因此需要新的存储后端。</li></ul><p><strong>二、讨论的主要议题</strong></p><ol><li><p><strong>文件存储的局限性</strong>：</p><ul><li>POSIX 接口限制，无法提供原子性事务。</li><li>文件系统遍历效率低，不适合大量对象存储。</li><li>需要使用复杂的目录结构来模拟对象存储。</li></ul></li><li><p><strong>新存储 (New Store)</strong>：</p><ul><li>使用 RocksDB 作为键值数据库来存储元数据。</li><li>对象数据存储在 POSIX 文件中。</li><li>存在日志和文件系统日志的双重开销，性能不佳。</li></ul></li><li><p><strong>蓝存储 (Blue Store)</strong>：</p><ul><li>结合了新存储和块设备的特点。</li><li>使用 RocksDB 存储元数据。</li><li>对象数据直接写入块设备。</li><li>提供原子性事务、高效的对象枚举、克隆和压缩功能。</li></ul></li></ol><p><strong>三、决定的事项</strong></p><ul><li>将 Blue Store 作为 Rados 的候选存储后端。</li><li>在 Jewel 和最新 master 版本中提供 Blue Store 的实验性支持。</li><li>进行性能测试和优化。</li><li>将 Blue Store 集成到 Kraken 版本中，作为默认存储后端。</li></ul><p><strong>四、后续行动计划</strong></p><ul><li>完善元数据编码效率。</li><li>支持 ZetaScale 作为 RocksDB 的替代方案。</li><li>优化压缩和检查和功能。</li><li>添加池级别属性，支持不同的数据存储策略。</li><li>开发 SMR 硬盘支持。</li><li>支持 SPDK，优化 NVMe 设备性能。</li></ul><p><strong>五、关键术语</strong></p><ul><li>Ceph</li><li>Rados</li><li>RocksDB</li><li>POSIX</li><li>Blue Store</li><li>New Store</li><li>原子性事务</li><li>对象枚举</li><li>克隆</li><li>压缩</li><li>检查和</li><li>BlueFS</li><li>RocksDB</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>cephfs</li><li>rbd</li><li>radosgw</li><li>RGW</li><li>RESTful API</li><li>authentication</li><li>authorization</li><li>encryption</li><li>erasure coding</li><li>replication</li><li>snapshots</li><li>clones</li><li>thin provisioning</li><li>iSCSI</li><li>Fibre Channel</li><li>NFS</li><li>CIFS</li><li>POSIX</li><li>monitoring</li><li>dashboard</li><li>management</li><li>orchestration</li><li>automation</li><li>integration</li><li>containerization</li><li>Kubernetes</li><li>Docker</li><li>virtualization</li><li>cloud computing</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>hybrid cloud</li><li>multi-cloud</li><li>storage cluster</li><li>node</li><li>disk</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>network</li><li>topology</li><li>failure domain</li><li>recovery</li><li>resilience</li><li>load balancing</li><li>caching</li><li>compression</li><li>deduplication</li><li>tiering</li><li>performance tuning</li><li>benchmarking</li><li>testing</li><li>validation</li><li>checksum</li><li>inline compression</li></ul>',16)])])}const d=i(s,[["render",r]]);export{g as __pageData,d as default};
